use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts whole seconds since the Unix epoch (UTC) to a proleptic
/// Gregorian (year, month, day). Uses Howard Hinnant's civil_from_days.
fn civil_from_secs(secs: u64) -> (i64, u32, u32) {
    let z = (secs / 86_400) as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // One clock read serves both fields, so `date` and `started`
        // describe the same instant.
        let now = wall_clock::now();
        let secs = now.seconds;

        let (y, m, d) = civil_from_secs(secs);

        // The ensure `len(date) == 10` requires a four-digit year.
        // Aborting here is preferable to emitting a non-conforming output.
        if !(0..=9999).contains(&y) {
            panic!("year {y} is outside the 4-digit range required by the date contract");
        }

        let date = format!("{:04}-{:02}-{:02}", y, m, d);
        debug_assert_eq!(date.len(), 10);

        RunInfo {
            date,
            started: secs,
        }
    }
}

export!(Node);
